<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';require_once __DIR__.'/../src/Finance/Accounting/DatevExport.php';
use Kulturhus\Verein\{Database,Finance,DatevExport,TaxCatalog};
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);$db->exec("INSERT INTO clubs VALUES('a','Synthetic');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('admin','a','member',1)");$f=new Finance($db,'admin');$bank=$f->createAccount('Synthetic bank','offline','0','2025-01-01');$f->saveAccountSettings($bank,0,true,'18000');$key=fn()=>bin2hex(random_bytes(16));$n=0;function check($v,$label){global $n;if(!$v)throw new RuntimeException($label);++$n;echo "PASS $label\n";}
$income='';foreach($f->taxAccounts(2025) as $code=>$a)if($a['category']==='revenue'&&$a['active']&&!preg_match('/AM|AV/',$a['function']??'')){$income=(string)$code;break;}
foreach(TaxCatalog::supportedKeys(2025) as $code=>$r){$expense=$r['direction']==='expense';$rate=$r['local_rate'];$gross=$rate===19?'119':'107';$entry=$f->createEntry(['kind'=>$expense?'expense':'income','description'=>'Synthetic domestic rule '.$code,'category'=>'general','document_date'=>'2025-04-05','due_date'=>'2025-04-05','positions'=>[['description'=>'Synthetic domestic rule '.$code,'amount'=>$gross,'tax_rate'=>(string)$rate,'sphere'=>'3','account'=>$expense?'68000':$income,'booking_key'=>(string)$code,'input_tax'=>$expense?'deductible':'unknown']]],$key());$f->recordPayment($entry,1,$bank,'2025-04-05');check($f->positions('entry',$entry)[0]['catalog_year']===2025,'2025 account snapshot key '.$code);}
$export=new DatevExport($db,'admin');$options=['from'=>'2025-01-01','to'=>'2025-12-31','advisor'=>'1001','client'=>'1'];$p=$export->preview($options);check($p['errors']===[],'all eight verified 2025 rules exported');$csv=$export->download($options,$p['hash']);check(str_contains($csv,'"0401"')&&str_contains($csv,'"0101"'),'modern BU codes preserved');check($p['options']['bank_codes'][$bank]==='18000','permanent money account mapping used without repeated input');$f->saveAccountSettings($bank,1,false,'18000');check($export->preview($options)['errors']===[],'historical export remains possible after money account disabled');check(TaxCatalog::supportedKeys(2024)===[],'unverified years fail closed');echo "$n DATEV 2025 checks passed\n";
